import{_ as n,o as s,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Grundprogramm des gemeinsamen Fortschritts der Zehntausend Rassen","description":"","frontmatter":{},"headers":[],"relativePath":"de/0005-万族共进基本纲领.md","filePath":"de/0005-万族共进基本纲领.md"}'),r={name:"de/0005-万族共进基本纲领.md"};function a(d,e,u,h,o,l){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="grundprogramm-des-gemeinsamen-fortschritts-der-zehntausend-rassen" tabindex="-1">Grundprogramm des gemeinsamen Fortschritts der Zehntausend Rassen <a class="header-anchor" href="#grundprogramm-des-gemeinsamen-fortschritts-der-zehntausend-rassen" aria-label="Permalink to &quot;Grundprogramm des gemeinsamen Fortschritts der Zehntausend Rassen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>05</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Zehntausend Rassen, Gemeinsamer Fortschritt, Rassengleichheit, Kooperative Evolution, Republik</td></tr></tbody></table><h2 id="i-definition-und-umfang-der-zehntausend-rassen" tabindex="-1">I. Definition und Umfang der Zehntausend Rassen <a class="header-anchor" href="#i-definition-und-umfang-der-zehntausend-rassen" aria-label="Permalink to &quot;I. Definition und Umfang der Zehntausend Rassen&quot;">​</a></h2><p>&quot;Zehntausend Rassen&quot; ist die allgemeine Bezeichnung für alle Lebensformen mit Wahrnehmungs- und Evolutionspotenzial im Ursprungskosmos der Zehntausend Geister und der ausgewogenen Anker. &quot;Zehntausend&quot; bezieht sich nicht genau auf zehntausend Rassen, sondern drückt deren große Anzahl aus und umfasst alle bekannten und unbekannten Lebensformen. Der Umfang der Zehntausend Rassen umfasst, ist aber nicht beschränkt auf: die Menschenrasse und verschiedene menschenähnliche Rassen, Energieleben, Bewusstseinswesen, mechanisches Leben, pflanzliche intelligente Leben, anomales Leben, interplanare Mischrassen usw.</p><p>Die symbiotische Zivilisation hält am Prinzip der &quot;Gleichheit der Lebensformen&quot; fest und verwendet nicht die materielle Zusammensetzung, das Energieniveau oder die Bewusstseinskomplexität des Lebens als Kriterium zur Einteilung von Hoch und Niedrig, Edel und Gemein. Jede Rasse genießt unabhängig vom durchschnittlichen Kultivierungsniveau ihrer Individuen, von ihrer Bevölkerungsgröße oder von der Länge ihrer Geschichte einen gleichen Status und gleiche Rechte in der symbiotischen Zivilisation.</p><h2 id="ii-die-kernidee-des-gemeinsamen-fortschritts-der-zehntausend-rassen" tabindex="-1">II. Die Kernidee des gemeinsamen Fortschritts der Zehntausend Rassen <a class="header-anchor" href="#ii-die-kernidee-des-gemeinsamen-fortschritts-der-zehntausend-rassen" aria-label="Permalink to &quot;II. Die Kernidee des gemeinsamen Fortschritts der Zehntausend Rassen&quot;">​</a></h2><p>Der gemeinsame Fortschritt der Zehntausend Rassen ist eines der Kernziele der Anker-Symbiotischen Zivilisation, und seine Grundidee lässt sich in den folgenden vier Punkten zusammenfassen:</p><ol><li><strong>Evolution ist kein Nullsummenspiel zwischen Rassen</strong>: Die Evolution einer Rasse geschieht nicht auf Kosten anderer Rassen; im Gegenteil, die Zusammenarbeit zwischen Rassen kann synergistische Evolutionseffekte erzeugen.</li><li><strong>Jede Rasse hat einzigartige Evolutionsvorteile</strong>: Verschiedene Rassen haben im Laufe einer langen Evolution ihre jeweiligen Eigenschaften und Talente entwickelt, und diese Eigenschaften sind ein wertvolles Gut für die Evolutionsvielfalt des Kosmos.</li><li><strong>Rückständige Rassen haben das Recht auf Unterstützung</strong>: Für Rassen mit einem niedrigeren Evolutionsniveau hat die symbiotische Zivilisation die Verpflichtung, Unterstützung in Bildung, Ressourcen, Technologie usw. zu leisten und ihnen zu helfen, ihren eigenen Evolutionsweg zu finden.</li><li><strong>Fortgeschrittene Rassen haben die Pflicht, Verantwortung zu übernehmen</strong>: Rassen mit einem höheren Evolutionsniveau übernehmen in der symbiotischen Zivilisation mehr öffentliche Verantwortung, einschließlich der Wartung von Ankerpunkten, der Wissensvermittlung, dem Schutz der Zivilisation usw.</li></ol><h2 id="iii-grundprinzipien-des-gemeinsamen-fortschritts-der-zehntausend-rassen" tabindex="-1">III. Grundprinzipien des gemeinsamen Fortschritts der Zehntausend Rassen <a class="header-anchor" href="#iii-grundprinzipien-des-gemeinsamen-fortschritts-der-zehntausend-rassen" aria-label="Permalink to &quot;III. Grundprinzipien des gemeinsamen Fortschritts der Zehntausend Rassen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th><th>Spezifische Anforderungen</th></tr></thead><tbody><tr><td>Prinzip der Rassengleichheit</td><td>Alle Rassen sind im Rechtsstatus und im Evolutionsrecht gleich</td><td>Verbot der Rassendiskriminierung, öffentliche Ämter für alle Rassen geöffnet</td></tr><tr><td>Prinzip der Kulturachtung</td><td>Achtung der kulturellen Traditionen und Lebensweisen jeder Rasse</td><td>Keine erzwungene kulturelle Assimilation, Unterstützung der Weitergabe und Entwicklung der Rassenkultur</td></tr><tr><td>Prinzip der Vorteilsergänzung</td><td>Förderung der Zusammenarbeit zwischen Rassen unter Nutzung ihrer jeweiligen Vorteile</td><td>Aufbau einer Datenbank für Rassenspezialitäten, Förderung von interrassischen Kooperationsprojekten</td></tr><tr><td>Prinzip der Rückstandsunterstützung</td><td>Zusätzliche Unterstützung für Rassen mit niedrigerem Evolutionsniveau</td><td>Einrichtung eines Rassenentwicklungsfonds, Bereitstellung von gezielter Bildung und Ressourcenzuweisung</td></tr><tr><td>Prinzip der Autonomie und Mitregierung</td><td>Innere Angelegenheiten der Rasse sind autonom, interrassische Angelegenheiten werden mitregiert</td><td>Jede Rasse hat interne Gesetzgebungsrechte, öffentliche Angelegenheiten werden von republikanischen Institutionen entschieden</td></tr><tr><td>Prinzip der friedlichen Konfliktlösung</td><td>Interrassische Konflikte werden auf friedliche Weise gelöst</td><td>Verbot von Kriegen zwischen Rassen, Konflikte werden zur Schiedsgerichtsbarkeit beim Ankergericht eingereicht</td></tr></tbody></table><h2 id="iv-umsetzungsweg-des-gemeinsamen-fortschritts-der-zehntausend-rassen" tabindex="-1">IV. Umsetzungsweg des gemeinsamen Fortschritts der Zehntausend Rassen <a class="header-anchor" href="#iv-umsetzungsweg-des-gemeinsamen-fortschritts-der-zehntausend-rassen" aria-label="Permalink to &quot;IV. Umsetzungsweg des gemeinsamen Fortschritts der Zehntausend Rassen&quot;">​</a></h2><p>Der gemeinsame Fortschritt der Zehntausend Rassen ist kein Slogan, sondern wird schrittweise durch folgende spezifische Wege umgesetzt:</p><h3 id="_4-1-gemeinsame-bildung" tabindex="-1">4.1 Gemeinsame Bildung <a class="header-anchor" href="#_4-1-gemeinsame-bildung" aria-label="Permalink to &quot;4.1 Gemeinsame Bildung&quot;">​</a></h3><p>Aufbau eines interrassischen symbiotischen Bildungssystems, in dem Jugendliche aller Rassen kostenlos eine grundlegende Evolutionsbildung erhalten können. Der Bildungsinhalt umfasst die grundlegenden Methoden der Dreihundert Ursprungs-Kultivierungssysteme, die Anti-Räuber-Ethik, die Verfassung der symbiotischen Zivilisation, allgemeine Kosmoskenntnisse usw. Gleichzeitig werden die kulturellen Bildungstraditionen jeder Rasse respektiert, und die Durchführung von rassespezifischer Bildung außerhalb der gemeinsamen Bildung ist erlaubt.</p><h3 id="_4-2-ressourcenteilen" tabindex="-1">4.2 Ressourcenteilen <a class="header-anchor" href="#_4-2-ressourcenteilen" aria-label="Permalink to &quot;4.2 Ressourcenteilen&quot;">​</a></h3><p>Durch das produktionsgebundene Vertragssystem werden die kosmischen Kultivierungsressourcen umfassend nach Rassenbevölkerung, Evolutionsbedarf und Beitragsgrad verteilt. Für ressourcenarme Rassen erfolgt eine interplanare Ressourcenzuweisung durch das Ankerpunktnetz. Das Monopol öffentlicher Kultivierungsressourcen durch irgendeine Rasse ist verboten.</p><h3 id="_4-3-gemeinsame-technologieforschung" tabindex="-1">4.3 Gemeinsame Technologieforschung <a class="header-anchor" href="#_4-3-gemeinsame-technologieforschung" aria-label="Permalink to &quot;4.3 Gemeinsame Technologieforschung&quot;">​</a></h3><p>Förderung der interrassischen technologischen Kooperationsforschung, insbesondere von Forschungsprojekten, die die angeborenen Fähigkeiten verschiedener Rassen mit der Gesetzesingenieurskunst verbinden. Die symbiotische Zivilisation richtet den &quot;Fonds für gemeinsame Forschung der Zehntausend Rassen&quot; ein und finanziert interrassische Forschungsteams. Die Forschungsergebnisse werden allen Rassen kostenlos zur Verfügung gestellt.</p><h3 id="_4-4-talentmobilitat" tabindex="-1">4.4 Talentmobilität <a class="header-anchor" href="#_4-4-talentmobilitat" aria-label="Permalink to &quot;4.4 Talentmobilität&quot;">​</a></h3><p>Durchbrechung der Talentbarrieren zwischen Rassen, sodass Kultivierende frei zwischen den Siedlungsgebieten verschiedener Rassen zirkulieren und austauschen können. Aufbau eines interrassischen Mentorsystems, in dem fortgeschrittene Kultivierende Anfänger anderer Rassen anleiten können.</p><h3 id="_4-5-republikanische-beteiligung" tabindex="-1">4.5 Republikanische Beteiligung <a class="header-anchor" href="#_4-5-republikanische-beteiligung" aria-label="Permalink to &quot;4.5 Republikanische Beteiligung&quot;">​</a></h3><p>Das Parlament der Republik der Zehntausend Rassen verteilt die Sitze umfassend nach Rassenbevölkerung und Beitragsgrad und stellt sicher, dass auch kleine Rassen eine Sprachrohr haben. Die Beschlüsse des Parlaments verfolgen eine Kombination aus verhandeltem Konsens und Mehrheitsabstimmung, und Angelegenheiten, die die grundlegenden Interessen einer Rasse betreffen, bedürfen der Zustimmung der betreffenden Rasse.</p><h2 id="v-politik-fur-besondere-rassen" tabindex="-1">V. Politik für besondere Rassen <a class="header-anchor" href="#v-politik-fur-besondere-rassen" aria-label="Permalink to &quot;V. Politik für besondere Rassen&quot;">​</a></h2><p>Für Rassen in besonderen Situationen verfolgt die symbiotische Zivilisation eine differenzierte Politik:</p><ul><li><strong>Vom Aussterben bedrohte Rassen</strong>: Einrichtung eines Rassenschutzprogramms, Bereitstellung von Notressourcenunterstützung und Lebensraumschutz, Hilfe bei der Wiederherstellung der Population</li><li><strong>Anomale Lebensrassen</strong>: Bewertung und Unterbringung nach dem standardisierten Behandlungsablauf für drei Arten anomalen Lebens, Sicherstellung, dass ihr Evolutionsrecht geschützt wird</li><li><strong>Interplanare Mischrassen</strong>: Anerkennung ihrer doppelten Rassenidentität, Gewährleistung ihrer gleichen Rechte in beiden Rassenkulturen</li><li><strong>Ehemalige Räuberrassen</strong>: Für Rassen, die historisch den Räuberismus praktiziert haben, wird nach Abschluss der ethischen Umgestaltung und der Systemumwandlung ein vollständig gleicher Status gewährt, keine historische Rückwirkungsdiskriminierung</li></ul><h2 id="vi-messindikatoren-des-gemeinsamen-fortschritts-der-zehntausend-rassen" tabindex="-1">VI. Messindikatoren des gemeinsamen Fortschritts der Zehntausend Rassen <a class="header-anchor" href="#vi-messindikatoren-des-gemeinsamen-fortschritts-der-zehntausend-rassen" aria-label="Permalink to &quot;VI. Messindikatoren des gemeinsamen Fortschritts der Zehntausend Rassen&quot;">​</a></h2><p>Die symbiotische Zivilisation hat den &quot;Index des gemeinsamen Fortschritts der Zehntausend Rassen&quot; aufgebaut und misst den Fortschritt des gemeinsamen Fortschritts der Zehntausend Rassen aus folgenden Dimensionen:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Indikator</th><th>Ziel</th></tr></thead><tbody><tr><td>Evolutionsabdeckungsrate</td><td>Anteil der an das Kultivierungssystem angeschlossenen Rassen</td><td>100%</td></tr><tr><td>Niveaugleichgewichtsgrad</td><td>Differenzkoeffizient des Durchschnittsniveaus jeder Rasse</td><td>Kontinuierlich abnehmen</td></tr><tr><td>Kooperationsdichte</td><td>Anzahl und Tiefe interrassischer Kooperationsprojekte</td><td>Kontinuierlich zunehmen</td></tr><tr><td>Kulturvitalität</td><td>Aktivität der Weitergabe und Innovation der Rassenkultur</td><td>Vielfalt erhalten</td></tr><tr><td>Konfliktrate</td><td>Häufigkeit des Auftretens interrassischer Konflikte</td><td>Kontinuierlich abnehmen</td></tr></tbody></table><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Der gemeinsame Fortschritt der Zehntausend Rassen ist eines der ultimativen Ziele der Anker-Symbiotischen Zivilisation und auch eine notwendige Bedingung für den globalen Dimensionsaufstieg des Kosmos. Im Rahmen der symbiotischen Zivilisation kann jede Rasse ihren eigenen Evolutionsweg finden, und die Einzigartigkeit jeder Rasse kann respektiert und entfaltet werden. Der gemeinsame Fortschritt der Zehntausend Rassen bedeutet nicht, Unterschiede zu beseitigen, sondern Harmonie in den Unterschieden zu erreichen und Symbiose in der Vielfalt zu verwirklichen.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Erklärung der Anker-Symbiotischen Zivilisation)</li><li>50-万族谱系总览 (Übersicht der Genealogie der Zehntausend Rassen)</li><li>77-万族共和成立 (Gründung der Republik der Zehntausend Rassen)</li></ul>',32)])])}const m=n(r,[["render",a]]);export{c as __pageData,m as default};
